args.old_string:
// AddInterval returns t moved forward by one billing interval: a month or a year.
func AddInterval(t time.Time, iv store.Interval) time.Time {
	if iv == store.Yearly {
		return t.AddDate(1, 0, 0)
	}
	return t.AddDate(0, 1, 0)
}

args.new_string:
// Anchor returns the start of a subscription's first paid period: its trial end for one that started with a trial, and
// otherwise its start. Billing periods are counted from the anchor.
func Anchor(sub store.Subscription) time.Time {
	if sub.TrialEnd != nil {
		return sub.TrialEnd.UTC()
	}
	return sub.StartedAt.UTC()
}

// PeriodStart returns the start of period n (n = 0, 1, 2, ...) of a billing schedule anchored at anchor: n intervals after
// the anchor, on the anchor's day of the month and at its time of day, in UTC. When that month is shorter, the period starts
// on its last day. Each period is computed from the anchor, so a short month does not move later periods.
func PeriodStart(anchor time.Time, iv store.Interval, n int) time.Time {
	anchor = anchor.UTC()
	months := n
	if iv == store.Yearly {
		months = 12 * n
	}
	first := time.Date(anchor.Year(), anchor.Month()+time.Month(months), 1, 0, 0, 0, 0, time.UTC)
	lastDay := first.AddDate(0, 1, -1).Day()
	day := min(anchor.Day(), lastDay)
	return time.Date(first.Year(), first.Month(), day, anchor.Hour(), anchor.Minute(), anchor.Second(), anchor.Nanosecond(), time.UTC)
}

// PeriodIndex returns n such that PeriodStart(anchor, iv, n) is t, for t a period boundary of that schedule.
func PeriodIndex(anchor, t time.Time, iv store.Interval) int {
	anchor, t = anchor.UTC(), t.UTC()
	months := (t.Year()-anchor.Year())*12 + int(t.Month()-anchor.Month())
	if iv == store.Yearly {
		return months / 12
	}
	return months
}

// AddInterval returns t moved forward by one billing interval: a month or a year. On the last day of a month it lands on the
// last day of the next one.
func AddInterval(t time.Time, iv store.Interval) time.Time {
	return PeriodStart(t, iv, 1)
}

