	// Each period starts where the previous one ended and is renewed in turn, so a run that is late by several periods
	// renews every missed one, each with its own invoice. The loop stops at the period that contains now.
	anchor := billing.Anchor(sub)
	n := billing.PeriodIndex(anchor, sub.CurrentPeriodEnd, plan.Interval)
	declined := false
	for !sub.CurrentPeriodEnd.After(now) {
		start := billing.PeriodStart(anchor, plan.Interval, n)
		end := billing.PeriodStart(anchor, plan.Interval, n+1)
		paid := true
		var err error
		switch {
		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		case plan.UsageType == store.Licensed:
			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
		}
		if err != nil {
			return err
		}
		declined = declined || !paid
		status := store.Active
		if declined {
			status = store.PastDue
		}
		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.CurrentPeriodStart, x.CurrentPeriodEnd, x.Status = start, end, status
			return nil
		})
		if err != nil {
			return err
		}
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
		n++
	}
	return nil
}

