func TestRenewalKeepsTheAnchorDayAtMonthEnd(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.Clock.Set(time.Date(2026, 1, 31, 9, 0, 0, 0, time.UTC))
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	for _, next := range []time.Time{
		time.Date(2026, 2, 28, 9, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 31, 9, 0, 0, 0, time.UTC),
		time.Date(2026, 4, 30, 9, 0, 0, 0, time.UTC),
	} {
		e.Clock.Set(next)
		if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
			t.Fatalf("RenewDue at %v = %d, %v", next, n, err)
		}
		got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
		if !got.CurrentPeriodStart.Equal(next) || !got.CurrentPeriodEnd.Equal(billing.PeriodStart(sub.StartedAt, store.Monthly, 1+periodsSince(sub.StartedAt, next))) {
			t.Fatalf("period at %v = %v to %v", next, got.CurrentPeriodStart, got.CurrentPeriodEnd)
		}
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if !got.CurrentPeriodEnd.Equal(time.Date(2026, 5, 31, 9, 0, 0, 0, time.UTC)) {
		t.Fatalf("after three renewals the period ends %v, want May 31", got.CurrentPeriodEnd)
	}
}

func TestLateRenewalRenewsEveryMissedPeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.Clock.Set(time.Date(2026, 1, 31, 9, 0, 0, 0, time.UTC))
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	// The renewal job did not run for two months.
	e.Clock.Set(time.Date(2026, 4, 2, 17, 45, 0, 0, time.UTC))
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 2 {
		t.Fatalf("RenewDue = %d, %v; want 2 missed periods", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if !got.CurrentPeriodStart.Equal(time.Date(2026, 3, 31, 9, 0, 0, 0, time.UTC)) || !got.CurrentPeriodEnd.Equal(time.Date(2026, 4, 30, 9, 0, 0, 0, time.UTC)) {
		t.Fatalf("current period = %v to %v", got.CurrentPeriodStart, got.CurrentPeriodEnd)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 3 {
		t.Fatalf("invoices = %d, want one per period", len(invs))
	}
	for i, want := range []time.Time{time.Date(2026, 1, 31, 9, 0, 0, 0, time.UTC), time.Date(2026, 2, 28, 9, 0, 0, 0, time.UTC), time.Date(2026, 3, 31, 9, 0, 0, 0, time.UTC)} {
		if invs[i].PeriodStart == nil || !invs[i].PeriodStart.Equal(want) {
			t.Errorf("invoice %d period start = %v, want %v", i, invs[i].PeriodStart, want)
		}
	}
	if n, _ := e.Subs.RenewDue(ctx); n != 0 {
		t.Fatalf("renewed again: %d", n)
	}
}

