	anchor := time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC)
	if got := PeriodStart(anchor, store.Yearly, 1); !got.Equal(time.Date(2029, 2, 28, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("yearly, common year: %v", got)
	}
	if got := PeriodStart(anchor, store.Yearly, 4); !got.Equal(time.Date(2032, 2, 29, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("yearly, leap year: %v", got)
	}
	if got := PeriodStart(anchor, store.Monthly, 1); !got.Equal(time.Date(2028, 3, 29, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("monthly: %v", got)
	}
}

