	anchor := time.Date(2026, 1, 31, 9, 0, 0, 0, time.UTC)
	for n := 0; n < 14; n++ {
		if got := PeriodIndex(anchor, PeriodStart(anchor, store.Monthly, n), store.Monthly); got != n {
			t.Errorf("monthly index of period %d = %d", n, got)
		}
	}
	if got := PeriodIndex(anchor, time.Date(2029, 1, 31, 9, 0, 0, 0, time.UTC), store.Yearly); got != 3 {
		t.Errorf("yearly index = %d", got)
	}
}

