	if got := AddInterval(time.Date(2026, 1, 31, 0, 0, 0, 0, time.UTC), store.Monthly); !got.Equal(time.Date(2026, 2, 28, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("Jan 31 + 1 month = %v", got)
	}
}

func TestAnchor(t *testing.T) {
	start := time.Date(2026, 1, 31, 8, 0, 0, 0, time.UTC)
	trialEnd := time.Date(2026, 2, 14, 8, 0, 0, 0, time.UTC)
	if got := Anchor(store.Subscription{StartedAt: start}); !got.Equal(start) {
		t.Errorf("without a trial: %v", got)
	}
	if got := Anchor(store.Subscription{StartedAt: start, TrialEnd: &trialEnd}); !got.Equal(trialEnd) {
		t.Errorf("with a trial: %v", got)
	}
