	if got := PeriodStart(anchor, store.Monthly, 1); !got.Equal(time.Date(2028, 3, 29, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("monthly: %v", got)
	}
}

func TestPeriodIndex(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 9, 0, 0, 0, time.UTC)
	for n := 0; n < 14; n++ {
		if got := PeriodIndex(anchor, PeriodStart(anchor, store.Monthly, n), store.Monthly); got != n {
			t.Errorf("monthly index of period %d = %d", n, got)
		}
	}
	if got := PeriodIndex(anchor, time.Date(2029, 1, 31, 9, 0, 0, 0, time.UTC), store.Yearly); got != 3 {
		t.Errorf("yearly index = %d", got)
	}
}

func TestAddIntervalOnMonthEnd(t *testing.T) {
	if got := AddInterval(time.Date(2026, 1, 31, 0, 0, 0, 0, time.UTC), store.Monthly); !got.Equal(time.Date(2026, 2, 28, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("Jan 31 + 1 month = %v", got)
	}
}

func TestAnchor(t *testing.T) {
	start := time.Date(2026, 1, 31, 8, 0, 0, 0, time.UTC)
	trialEnd := time.Date(2026, 2, 14, 8, 0, 0, 0, time.UTC)
	if got := Anchor(store.Subscription{StartedAt: start}); !got.Equal(start) {
		t.Errorf("without a trial: %v", got)
	}
	if got := Anchor(store.Subscription{StartedAt: start, TrialEnd: &trialEnd}); !got.Equal(trialEnd) {
		t.Errorf("with a trial: %v", got)
	}
}
